// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.seedMarket{value: 1 ether}(1000);

        vm.prank(c.ceoAddress());
        c.DrugDealer();

        address user = address(0x2);
        vm.prank(user);
        c.getFreeKilo();

        uint256 kilos = c.Kilos(user);
        assertTrue(kilos == 300, "Kilos should be 300 in reference, but mutant gives 200");
    }
}
